import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createAdoptRequestEvidence,auditAdoptRequestEvidence} from '../scripts/adopt-request-evidence.mjs';
import {account} from '../scripts/network-accounting.mjs';
import {canonical,sha} from '../scripts/release-core.mjs';
import {classifyRequestSignals,clickObserverSource} from '../scripts/adopt-causal-bridge.mjs';
// Immutable independently captured Chromium fixture, not generated by this test's implementation.
const captured=JSON.parse(fs.readFileSync(new URL('./fixtures/adopt-independent-positive.json',import.meta.url)));
function positive(){const f=structuredClone(captured);f.origin=f.evidence.requests[0].metadata.origin;f.raw=f.result.ledger.map(x=>({...x.event,url:x.event.origin+'/niveles-estadisticos'}));return f;}
function reindex(e){e.journal.forEach((x,i)=>x.sequence=i+1);for(const r of e.requests)r.event_sequences=e.journal.filter(x=>x.request_id===r.request_id).map(x=>x.sequence);}
const audit=f=>auditAdoptRequestEvidence(f.evidence,f.raw,f.result,f.origin,['T1']);
test('independent complete positive action: browser IDs, receipt, lifecycle and accounting agree',()=>{const f=positive();assert.deepEqual(audit(f),{status:'PASS',issues:[]});assert.equal(f.result.required_application_request_failures,0);assert.equal(f.evidence.actions.length,1);assert.equal(f.evidence.transition_receipts.records.length,1);assert.equal(f.result.ledger.length,1);});
// F24.6-1: mutate an independent captured fixture, preserving the original
// action/receipt/ledger and correcting only structural sequence indexing.
function unsupportedObservation(f,kind='TIMEOUT',scoped=true) {
 const e=f.evidence,r=e.requests[1],before=e.journal.findIndex(x=>x.kind==='FAILED');
 const observation={kind,native_event_type:'Network.loadingFailed',canceled:false,error_code:'net::ERR_TIMED_OUT',
  ...(scoped?{page_id:r.request_evidence.page_id,page_lifecycle:'ACTIVE',request_id:r.request_id,transition_id:r.transition_id}:{})};
 e.journal.splice(before,0,observation);reindex(e);return observation;
}
test('F24.6-1: unsupported timeout cannot bypass receipt and failure accounting',()=>{
 const f=positive();assert.deepEqual(audit(f),{status:'PASS',issues:[]});
 const observation=unsupportedObservation(f),before=structuredClone(f),validation=audit(f);
 assert.equal(validation.status,'FAIL');assert.ok(validation.issues.includes('UNSUPPORTED_JOURNAL_EVENT'));
 assert.deepEqual(f,before,'auditing must retain every observation without normalization');
 assert.ok(f.evidence.journal.includes(observation));assert.equal(f.result.required_application_request_failures,0,'rejection must not depend on a changed aggregate');
});
for(const kind of ['UNKNOWN','timeout','TIMEOUT ','constructor','__proto__','toString','',null,42,{},['FAILED']])
 test('journal vocabulary rejects malformed or unsupported kind '+JSON.stringify(kind),()=>{
  const f=positive();unsupportedObservation(f,kind);const validation=audit(f);
  assert.equal(validation.status,'FAIL');assert.ok(validation.issues.includes('UNSUPPORTED_JOURNAL_EVENT'));
 });
test('journal vocabulary rejects missing kind',()=>{const f=positive();delete unsupportedObservation(f).kind;const validation=audit(f);assert.equal(validation.status,'FAIL');assert.ok(validation.issues.includes('UNSUPPORTED_JOURNAL_EVENT'));});
test('unsupported failure cannot escape by removing request association',()=>{const f=positive();unsupportedObservation(f,'TIMEOUT',false);const validation=audit(f);assert.equal(validation.status,'FAIL');assert.ok(validation.issues.includes('UNSUPPORTED_JOURNAL_EVENT'));});
test('unsupported observation after freeze remains rejected and retained',()=>{const f=positive();const e=unsupportedObservation(f);f.evidence.journal.splice(f.evidence.journal.indexOf(e),1);f.evidence.journal.push(e);reindex(f.evidence);const validation=audit(f);assert.equal(validation.status,'FAIL');assert.ok(validation.issues.includes('UNSUPPORTED_JOURNAL_EVENT'));assert.ok(validation.issues.includes('EVENT_AFTER_FREEZE'));assert.equal(f.evidence.journal.at(-1),e);});
const attacks={
 'receipt order disagrees with observed completion':f=>{const j=f.evidence.journal,a=j.findIndex(x=>x.kind==='FAILED'),b=j.findIndex(x=>x.kind==='TRANSITION_COMPLETE');[j[a],j[b]]=[j[b],j[a]];reindex(f.evidence);},
 'two contradictory final response statuses':f=>{const j=f.evidence.journal,i=j.findIndex(x=>x.kind==='RESPONSE'&&x.request_id===f.evidence.requests[1].request_id);j.splice(i,0,{...j[i],status:201});reindex(f.evidence);},
 'journal exception omitted from ledger and denied by receipt':f=>{const j=f.evidence.journal,i=j.findIndex(x=>x.kind==='FAILED');j.splice(i,0,{kind:'APPLICATION_EXCEPTION',page_id:'page-1',page_lifecycle:'ACTIVE'});reindex(f.evidence);},
 'terminal receipt with pending lifecycle':f=>{f.evidence.requests[1].terminal_state='PENDING';f.evidence.journal=f.evidence.journal.filter(x=>x.kind!=='FAILED');reindex(f.evidence);},
 'completed lifecycle with abort receipt':f=>{f.evidence.requests[1].terminal_state='FINISHED';f.evidence.journal.find(x=>x.kind==='FAILED').kind='FINISHED';},
 'timeout lifecycle with abort receipt':f=>f.evidence.journal.find(x=>x.kind==='FAILED').error_code='net::ERR_TIMED_OUT',
 'terminal lifecycle with missing receipt':f=>f.evidence.transition_receipts.records=[],
 'nonterminal receipt':f=>f.evidence.transition_receipts.records[0].abort_sequence=0,
 'wrong receipt ownership':f=>f.evidence.transition_receipts.records[0].request_instance_id=f.evidence.requests[0].request_id,
 'stale receipt transition':f=>f.evidence.transition_receipts.records[0].transition_id='transition-2',
 'duplicate terminal receipt':f=>f.evidence.transition_receipts.records.push(structuredClone(f.evidence.transition_receipts.records[0])),
 'same receipt reused across transitions':f=>{const p=structuredClone(f.evidence.transition_receipts.records[0]);p.transition_id='transition-2';f.evidence.transition_receipts.records.push(p);},
 'retry claims wrong original parent':f=>{const r=f.evidence.requests[1];r.causal_parent=f.evidence.requests[0].request_id;r.causal_relation='CDP_INITIATOR_REQUEST';},
};
for(const [name,corrupt]of Object.entries(attacks))test('reconciliation rejects '+name,()=>{const f=positive();assert.equal(audit(f).status,'PASS');corrupt(f);assert.equal(audit(f).status,'FAIL');});
test('matching receipt and journal allow completion before abort without weakening original policy',()=>{const f=positive(),j=f.evidence.journal,a=j.findIndex(x=>x.kind==='FAILED'),b=j.findIndex(x=>x.kind==='TRANSITION_COMPLETE');[j[a],j[b]]=[j[b],j[a]];reindex(f.evidence);const p=f.evidence.transition_receipts.records[0];[p.abort_sequence,p.completion_sequence]=[p.completion_sequence,p.abort_sequence];f.result=account(f.raw,false,f.origin,f.evidence.transition_receipts);f.evidence.transition_accounting[0].receipt_ids=[sha(canonical(p))];f.evidence.receipt_decisions[0].receipt_id=sha(canonical(p));f.evidence.ledger_sha256=sha(canonical(f.result.ledger));assert.equal(audit(f).status,'PASS');});
function trace(){const origin='https://independent.invalid',page='page-1',c=createAdoptRequestEvidence(origin),raw=[];c.listenerStart(page);c.pageLifecycle(page,'ACTIVE');
 const request=(id,parent,redirect=false)=>c.request(page,{...(redirect?{redirectResponse:{status:307}}:{}),requestId:id,type:'Fetch',frameId:'frame',loaderId:'document',documentURL:origin+'/',request:{url:origin+'/'+id,method:'GET',headers:{'Next-Router-Prefetch':'0'}},initiator:{type:'script',...(parent?{requestId:parent}:{}),stack:{callFrames:[{scriptId:'independent-script',url:origin+'/app.js'}]}}});
 const exception=(id=17,type='Runtime.exceptionThrown',native)=>{const n=native??(type==='Runtime.exceptionThrown'?{exceptionDetails:{exceptionId:id}}:{}),event={kind:type==='Runtime.exceptionThrown'?'exception':'console_error',url:origin+'/',source:type};const binding=c.exception(page,n,event);if(binding)raw.push({...event,failure_evidence:binding});return n;};
 const close=()=>{c.pageLifecycle(page,'CLOSING');c.listenerDrain(page);};
 const freeze=()=>{c.sourceClosed(page);c.pageLifecycle(page,'CLOSED');c.freeze();};
 const view=()=>{const receipts=c.receipts(raw),result=account(raw,false,origin,receipts),evidence=c.evidence(raw,result,receipts);return {evidence,result,validation:auditAdoptRequestEvidence(evidence,raw,result,origin,[])};};
 return {origin,page,c,raw,request,exception,close,freeze,view};}
for(const where of ['before drain','during drain','after source close','after freeze'])test('captured exception retained '+where,()=>{const f=trace();if(where!=='before drain')f.close();if(where==='after source close'){f.c.sourceClosed(f.page);f.exception();f.c.pageLifecycle(f.page,'CLOSED');f.c.freeze();}else if(where==='after freeze'){f.freeze();f.exception();}else{f.exception();if(where==='before drain')f.close();f.freeze();}const v=f.view();assert.equal(v.result.hydration_errors,1);assert.equal(v.result.ledger.length,1);assert.equal(v.evidence.journal.filter(x=>x.kind==='APPLICATION_EXCEPTION').length,1);assert.equal(v.validation.status,['after source close','after freeze'].includes(where)?'FAIL':'PASS');});
for(const source of ['Runtime.exceptionThrown','Runtime.consoleAPICalled','Log.entryAdded'])test('native exception conversion and duplicate identity '+source,()=>{const f=trace(),n=f.exception(17,source);f.exception(17,source,n);f.close();f.freeze();const v=f.view();assert.equal(v.result.ledger.length,1);assert.equal(v.result.ledger[0].event.source,source);assert.equal(v.evidence.journal.filter(x=>x.kind==='EXCEPTION_DUPLICATE').length,1);assert.equal(v.validation.status,'PASS');assert.equal(v.result.application_console_errors+v.result.hydration_errors,1);});
test('serialized duplicate exception with explicit protocol identity is counted once',()=>{const f=trace();f.exception(21);f.exception(21);f.close();f.freeze();assert.equal(f.view().result.hydration_errors,1);});
test('distinct exceptions are not merged by timing or sanitized URL',()=>{const f=trace();f.exception(21);f.exception(22);f.close();f.freeze();assert.equal(f.view().result.hydration_errors,2);});
test('same native exception identity with contradictory sanitized meaning fails closed and retains conflict',()=>{const f=trace();f.exception(21);f.c.exception(f.page,{exceptionDetails:{exceptionId:21}},{kind:'exception',source:'Runtime.exceptionThrown',url:f.origin+'/different'});f.close();f.freeze();const v=f.view();assert.equal(v.validation.status,'FAIL');assert.equal(v.evidence.journal.find(x=>x.kind==='EXCEPTION_DUPLICATE').safe_event.path,sha('/different'));});
for(const name of ['omitted','invented','duplicated','wrong request','wrong transition','wrong native type'])test('exception accounting rejects '+name,()=>{const f=trace();f.request('parent');f.c.finished(f.page,{requestId:'parent'});f.exception();f.close();f.freeze();let v=f.view();assert.equal(v.validation.status,'PASS');
 if(name==='omitted')f.raw.length=0;
 if(name==='invented')v.evidence.journal=v.evidence.journal.filter(x=>x.kind!=='APPLICATION_EXCEPTION');
 if(name==='duplicated')f.raw.push(structuredClone(f.raw[0]));
 if(name==='wrong request')f.raw[0].failure_evidence.related_request_id=v.evidence.requests[0].request_id;
 if(name==='wrong transition')f.raw[0].failure_evidence.observed_transition_id='transition-99';
 if(name==='wrong native type')f.raw[0].failure_evidence.native_event_type='Runtime.consoleAPICalled';
 // Recompute aggregate/hash to exercise observation reconciliation, not a stale ledger hash.
 const result=account(f.raw,false,f.origin,v.evidence.transition_receipts);v.evidence.ledger_sha256=sha(canonical(result.ledger));reindex(v.evidence);
 assert.equal(auditAdoptRequestEvidence(v.evidence,f.raw,result,f.origin,[]).status,'FAIL');});
test('exception with exact native request reference passes; alternate same-page parent fails',()=>{const f=trace();f.request('parent');f.c.finished(f.page,{requestId:'parent'});f.request('other');f.c.finished(f.page,{requestId:'other'});f.exception(1,'Log.entryAdded',{entry:{networkRequestId:'parent'}});f.close();f.freeze();const v=f.view();assert.equal(v.validation.status,'PASS');assert.equal(v.result.ledger[0].event.failure_evidence.related_request_id,v.evidence.requests[0].request_id);v.evidence.journal.find(x=>x.kind==='APPLICATION_EXCEPTION').failure_evidence.related_request_id=v.evidence.requests[1].request_id;assert.equal(auditAdoptRequestEvidence(v.evidence,f.raw,v.result,f.origin,[]).status,'FAIL');});
for(const continuation of ['retry','successful sibling','partial response','duplicate terminal'])test('retained native failure followed by '+continuation,()=>{const f=trace(),binding=f.request('failed');f.c.response(f.page,{requestId:'failed',timestamp:1,response:{status:200}});const native={requestId:'failed',timestamp:2,canceled:false,errorText:'net::ERR_TIMED_OUT'};
 const failure=()=>{if(f.c.failure(f.page,native,f.raw.length)!==false)f.raw.push({request_evidence:binding,kind:'request_failure',url:f.origin+'/failed',type:'Fetch',rsc:false,prefetch:false,canceled:false,error_code:'net::ERR_TIMED_OUT'});};failure();
 if(continuation==='duplicate terminal')failure();else{const id=continuation==='retry'?'retry':'sibling';f.request(id,continuation==='retry'?'failed':undefined);if(continuation==='partial response')f.c.response(f.page,{requestId:id,response:{status:200}});else f.c.finished(f.page,{requestId:id});}
 f.close();f.freeze();const v=f.view();assert.equal(v.result.required_application_request_failures,1);assert.equal(v.result.ledger.length,1);assert.equal(v.evidence.requests[0].terminal_state,'FAILED');if(continuation==='retry')assert.equal(v.evidence.requests[1].causal_parent,v.evidence.requests[0].request_id);if(continuation==='duplicate terminal')assert.equal(v.evidence.journal.filter(x=>x.kind==='NATIVE_DUPLICATE').length,1);if(continuation==='partial response'){assert.equal(v.evidence.requests[1].terminal_state,'PENDING');assert.equal(v.validation.status,'FAIL');}else assert.equal(v.validation.status,'PASS');});
for(const source of ['Runtime.consoleAPICalled','Runtime.exceptionThrown','Log.entryAdded'])test('later successful request cannot erase '+source,()=>{const f=trace();f.exception(1,source);f.request('later');f.c.response(f.page,{requestId:'later',response:{status:200}});f.c.finished(f.page,{requestId:'later'});f.close();f.freeze();const v=f.view();assert.equal(v.validation.status,'PASS');assert.equal(v.result.application_console_errors+v.result.hydration_errors,1);});
test('combined negative: corrupt lifecycle, recorded exception, apparent success and ambiguous classification',()=>{const f=positive();attacks['receipt order disagrees with observed completion'](f);attacks['journal exception omitted from ledger and denied by receipt'](f);f.evidence.requests[1].terminal_state='FINISHED';f.evidence.requests[1].prefetch_classification='UNKNOWN';assert.equal(audit(f).status,'FAIL');});
for(const [headers,expected]of [[{RSC:'1','Next-Router-Prefetch':'1'},{rsc:'YES',prefetch:'YES'}],[{'Next-Router-Prefetch':'0'},{rsc:'NO',prefetch:'NO'}],[{RSC:'1'},{rsc:'YES',prefetch:'UNKNOWN'}],[{},{rsc:'NO',prefetch:'UNKNOWN'}]])test('native classification remains '+JSON.stringify(expected),()=>assert.deepEqual(classifyRequestSignals(headers),expected));
test('click conversion source preserves string hint and Symbol rejection',()=>{const source=clickObserverSource('fixture');assert.ok(source.includes('const name=`${type}`'));assert.ok(!source.includes("const name=''+type"));});

const browserEnabled=process.env.SL_CAUSAL_BROWSER_TEST==='1';
test('real Chromium native listener conversion, Symbol rejection, and captured listener exception',{skip:!browserEnabled},async()=>{
 const {chromium}=await import('../qa-dependencies/node_modules/playwright/index.mjs');const {once}=await import('node:events');const browser=await chromium.launch({headless:true});
 try {
  const outcomes=[];
  for(const wrapped of [false,true]){const ctx=await browser.newContext();if(wrapped)await ctx.addInitScript({content:clickObserverSource('independentBridge')});const p=await ctx.newPage();await p.goto('data:text/html,<button>test</button>');
   outcomes.push(await p.evaluate(()=>{const b=document.querySelector('button'),hints=[];let count=0;const type={[Symbol.toPrimitive](hint){hints.push(hint);return hint==='string'?'click':'wrong';}},fn=()=>count++;b.addEventListener(type,fn);b.click();b.removeEventListener(type,fn);b.click();let symbol;try{b.addEventListener(Symbol('type'),fn);symbol='accepted';}catch(e){symbol=e.name;}return {count,hints,symbol};}));
   if(wrapped){const cdp=await ctx.newCDPSession(p),f=trace();await cdp.send('Runtime.enable');cdp.on('Runtime.exceptionThrown',e=>f.exception(undefined,'Runtime.exceptionThrown',e));const observed=once(cdp,'Runtime.exceptionThrown');await p.evaluate(()=>{document.querySelector('button').addEventListener('click',()=>{throw new Error('independent native listener failure');});document.querySelector('button').click();});await observed;f.close();f.freeze();const v=f.view();assert.equal(v.result.hydration_errors,1);assert.equal(v.result.ledger[0].event.failure_evidence.identity_basis,'PROTOCOL_ID');assert.equal(v.validation.status,'PASS');}
   await ctx.close();
  }
  assert.deepEqual(outcomes[0],{count:1,hints:['string','string'],symbol:'TypeError'});assert.deepEqual(outcomes[1],outcomes[0]);
 }finally{await browser.close();}
});

