import os from 'node:os';
import path from 'node:path';
for(const timing of ['before drain','during drain','queued at close','duplicate exception','later success','duplicate failure'])test('shared harness durable retention '+timing,async()=>{
 const origin='https://harness.invalid',cdp=new EventEmitter();cdp.send=async()=>({result:{value:true}});
 const failure=()=>cdp.emit('Network.loadingFailed',{requestId:'failed',type:'Fetch',timestamp:2,canceled:false,errorText:'net::ERR_TIMED_OUT'});
 const exception=()=>cdp.emit('Runtime.exceptionThrown',{exceptionDetails:{exceptionId:39,url:origin+'/native-listener'}});
 const start=id=>cdp.emit('Network.requestWillBeSent',{requestId:id,type:'Fetch',frameId:'frame',loaderId:'doc',documentURL:origin+'/',request:{url:origin+'/'+id,method:'GET',headers:{'Next-Router-Prefetch':'0'}},initiator:{type:'script',stack:{callFrames:[{scriptId:'native',url:origin+'/app.js'}]}}});
 const context={newPage:async()=>({url:()=>origin}),newCDPSession:async()=>cdp,close:async()=>{if(timing==='during drain'){failure();exception();}cdp.emit('close');if(timing==='queued at close')setImmediate(()=>{failure();exception();});}};
 globalThis.__SL_RECON_PLAYWRIGHT={launch:async()=>({newContext:async()=>context,close:async()=>{}})};
 const url=new URL('../scripts/browser-harness-base.mjs',import.meta.url);let source=fs.readFileSync(url,'utf8');source=source.replace(/(['"])(\.\/[^'"]+\.mjs)\1/g,(_,q,v)=>JSON.stringify(new URL(v,url).href)).replace("await import('../qa-dependencies/node_modules/playwright/index.mjs')",'{chromium:globalThis.__SL_RECON_PLAYWRIGHT}');
 const {createReadOnlyHarness}=await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));
 const out=fs.mkdtempSync(path.join(os.tmpdir(),'sl-recon-retention-'));
 try{const h=await createReadOnlyHarness({origin},undefined,out,true),p=await h.createPage();start('failed');
 if(!['during drain','queued at close'].includes(timing)){failure();exception();if(timing==='duplicate exception')exception();if(timing==='duplicate failure')failure();if(timing==='later success'){start('later');cdp.emit('Network.responseReceived',{requestId:'later',response:{status:200,url:origin+'/later'},type:'Fetch'});cdp.emit('Network.loadingFinished',{requestId:'later'});}}
 await p.close();await assert.rejects(h.finish(true),/ADOPT_REQUEST_EVIDENCE_INVALID/);
 const e=JSON.parse(fs.readFileSync(out+'/adopt-request-evidence.json')),n=JSON.parse(fs.readFileSync(out+'/network-accounting.json'));
 assert.equal(n.required_application_request_failures,1);assert.equal(n.hydration_errors,1);assert.equal(n.ledger.length,2);assert.equal(e.journal.filter(x=>x.kind==='APPLICATION_EXCEPTION').length,1);assert.equal(e.journal.filter(x=>x.kind==='FAILED').length,1);assert.equal(e.validation.status,'FAIL');assert.equal(e.journal.filter(x=>x.kind==='ACCOUNTING_FREEZE').length,1);
 }finally{fs.rmSync(out,{recursive:true,force:true});}
});
test('missing terminal receipt cannot pass after all derived accounting is consistently recomputed',()=>{const f=positive();f.evidence.transition_receipts.records=[];f.evidence.receipt_decisions=[];f.evidence.transition_accounting[0].receipt_ids=[];f.result=account(f.raw,false,f.origin,f.evidence.transition_receipts);f.evidence.ledger_sha256=sha(canonical(f.result.ledger));assert.equal(f.result.required_application_request_failures,1);assert.ok(audit(f).issues.includes('MISSING_TERMINAL_RECEIPT'));});
