test('exception cannot bind to a stale redirect hop with the same native protocol ID',()=>{const f=trace();f.request('hop');f.request('hop',undefined,true);f.c.finished(f.page,{requestId:'hop'});f.exception(1,'Log.entryAdded',{entry:{networkRequestId:'hop'}});f.close();f.freeze();const v=f.view();assert.equal(v.validation.status,'PASS');assert.equal(v.result.ledger[0].event.failure_evidence.related_request_id,v.evidence.requests[1].request_id);const stale=v.evidence.requests[0].request_id;f.raw[0].failure_evidence.related_request_id=stale;v.evidence.journal.find(x=>x.kind==='APPLICATION_EXCEPTION').failure_evidence.related_request_id=stale;const result=account(f.raw,false,f.origin,v.evidence.transition_receipts);v.evidence.ledger_sha256=sha(canonical(result.ledger));assert.ok(auditAdoptRequestEvidence(v.evidence,f.raw,result,f.origin,[]).issues.includes('EXCEPTION_OWNERSHIP_MISMATCH'));});
