// F24.10-1: native source labels are independently supplied, never synthesized
// from the normalizer's output. Relative script labels have no proven base here.
function sourceFailure(f,url,native={exceptionDetails:{exceptionId:73}},source='Runtime.exceptionThrown',extra={}) {
 const raw={kind:source==='Runtime.exceptionThrown'?'exception':'console_error',source,url,...extra};
 const binding=f.c.exception(f.page,native,raw);if(binding)f.raw.push({...raw,failure_evidence:binding});return native;
}
for(const value of ['independent-relative.js','/path','./path','../path','?query=private-fixture-value','#fragment'])test('F24.10-1 retains unresolved relative source '+value,()=>{
 const f=trace();sourceFailure(f,value);f.close();f.freeze();const v=f.view(),row=v.result.ledger[0];
 assert.equal(v.result.ledger.length,1);assert.equal(v.result.unclassified_failures.length,1);assert.equal(v.validation.status,'FAIL');assert.ok(v.validation.issues.includes('SOURCE_URL_UNRESOLVED'));
 assert.equal(row.event.failure_evidence.related_request_id,'UNKNOWN');assert.equal(row.event.origin,'');assert.equal(row.event.path,'');assert.equal(row.event.source_url_evidence.raw_sha256,sha(value));
 assert.equal(row.event.source_url_evidence.normalization_status,'UNRESOLVED');assert.equal(row.event.source_url_evidence.normalization_failure,'MISSING_AUTHORITATIVE_BASE');
 assert.equal(v.evidence.journal.filter(j=>j.kind==='APPLICATION_EXCEPTION').length,1);assert.ok(!JSON.stringify(v).includes('private-fixture-value'));
});
